import{_ as e,c as r,o as h,af as i}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"15、【谦】 艮下坤上","description":"横渠易说 - 15、【谦】 艮下坤上","frontmatter":{"title":"15、【谦】 艮下坤上","description":"横渠易说 - 15、【谦】 艮下坤上"},"headers":[],"relativePath":"zh/classics/hengqu/017.md","filePath":"zh/classics/hengqu/017.md"}'),l={name:"zh/classics/hengqu/017.md"};function t(n,a,s,d,c,o){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="_15、【谦】-艮下坤上" tabindex="-1">15、【谦】 艮下坤上 <a class="header-anchor" href="#_15、【谦】-艮下坤上" aria-label="Permalink to “15、【谦】 艮下坤上”">​</a></h1><h3 id="彖曰-谦亨-天道下济而光明-地道卑而上行。天道亏盈而益谦-地道变盈而流谦-鬼神害盈而福谦-人道恶盈而好谦。谦尊而光-卑而不可踰-君子之终也。" tabindex="-1">彖曰：谦亨，天道下济而光明，地道卑而上行。天道亏盈而益谦，地道变盈而流谦，鬼神害盈而福谦，人道恶盈而好谦。谦尊而光，卑而不可踰，君子之终也。 <a class="header-anchor" href="#彖曰-谦亨-天道下济而光明-地道卑而上行。天道亏盈而益谦-地道变盈而流谦-鬼神害盈而福谦-人道恶盈而好谦。谦尊而光-卑而不可踰-君子之终也。" aria-label="Permalink to “彖曰：谦亨，天道下济而光明，地道卑而上行。天道亏盈而益谦，地道变盈而流谦，鬼神害盈而福谦，人道恶盈而好谦。谦尊而光，卑而不可踰，君子之终也。”">​</a></h3><p>止于下，故光明。人乐尊之，故光而不揜；志下于人，故人不能加。天以广大自然取贵，人自要尊大，须意、我、固、 必，欲顺己尊己，又悦己之情，此所以取辱取怒也。“谦尊而光，卑而不可踰”，夫尊者谦则更光，卑者已谦，又如何踰之!此天德至虚者焉。以其能谦，故尊而益光，卑又无人可踰，盖已谦矣，复如何踰越也!谦，天下之良德。</p><h3 id="象曰-地中有山-谦-君子以裒多益寡-称物平施。" tabindex="-1">象曰：地中有山，谦，君子以裒多益寡，称物平施。 <a class="header-anchor" href="#象曰-地中有山-谦-君子以裒多益寡-称物平施。" aria-label="Permalink to “象曰：地中有山，谦，君子以裒多益寡，称物平施。”">​</a></h3><p>隐高于卑，谦之象也。易大象皆是实事，卦爻小象则容有寓意而已。言“风自火出家人”，家人之道必自烹饪始；风，风也，教也，盖言教家人之道必自此始也。又如言“木上有水井”，则明言井之实事也。又言“地中有山谦”，夫山者崇高之物，非谦而何!又如言“云雷屯”，云雷皆是气之聚处，屯，聚也。多者寡者皆量宜下之。</p><h3 id="初六-谦谦君子-用涉大川-吉。-象曰-谦谦君子-卑以自牧也。" tabindex="-1">初六，谦谦君子，用涉大川，吉。 象曰：“谦谦君子”，卑以自牧也。 <a class="header-anchor" href="#初六-谦谦君子-用涉大川-吉。-象曰-谦谦君子-卑以自牧也。" aria-label="Permalink to “初六，谦谦君子，用涉大川，吉。 象曰：“谦谦君子”，卑以自牧也。”">​</a></h3><p>牧，逸也。</p><h3 id="六二-鸣谦-贞吉。-象曰-鸣谦贞吉-中心得也。" tabindex="-1">六二，鸣谦，贞吉。 象曰：“鸣谦贞吉”，中心得也。 <a class="header-anchor" href="#六二-鸣谦-贞吉。-象曰-鸣谦贞吉-中心得也。" aria-label="Permalink to “六二，鸣谦，贞吉。 象曰：“鸣谦贞吉”，中心得也。”">​</a></h3><p>体柔居正，故以谦获誉，与上六之鸣异矣，故曰“贞吉”，［中心安之也］。</p><h3 id="九三-劳谦-君子有终-吉。-象曰-劳谦君子-万民服也。" tabindex="-1">九三，劳谦，君子有终，吉。 象曰：“劳谦君子”，万民服也。 <a class="header-anchor" href="#九三-劳谦-君子有终-吉。-象曰-劳谦君子-万民服也。" aria-label="Permalink to “九三，劳谦，君子有终，吉。 象曰：“劳谦君子”，万民服也。”">​</a></h3><p>(中心安之也。)有终则吉，人所难能。</p><h3 id="六四-无不利-撝谦。-象曰-无不利撝谦-不违则也。" tabindex="-1">六四，无不利，撝谦。 象曰：“无不利撝谦”，不违则也。 <a class="header-anchor" href="#六四-无不利-撝谦。-象曰-无不利撝谦-不违则也。" aria-label="Permalink to “六四，无不利，撝谦。 象曰：“无不利撝谦”，不违则也。”">​</a></h3><p>裒多益寡，无不尽道，举措皆谦。</p><h3 id="六五-不富以其邻-利用侵伐-无不利。-象曰-利用侵伐-征不服也。" tabindex="-1">六五，不富以其邻，利用侵伐，无不利。 象曰：“利用侵伐”，征不服也。 <a class="header-anchor" href="#六五-不富以其邻-利用侵伐-无不利。-象曰-利用侵伐-征不服也。" aria-label="Permalink to “六五，不富以其邻，利用侵伐，无不利。 象曰：“利用侵伐”，征不服也。”">​</a></h3><h3 id="上六-鸣谦-利用行师-征邑国。-象曰-鸣谦-志未得也-可用行师-征邑国也。" tabindex="-1">上六，鸣谦，利用行师，征邑国。 象曰：“鸣谦”，志未得也，可用行师，征邑国也。 <a class="header-anchor" href="#上六-鸣谦-利用行师-征邑国。-象曰-鸣谦-志未得也-可用行师-征邑国也。" aria-label="Permalink to “上六，鸣谦，利用行师，征邑国。 象曰：“鸣谦”，志未得也，可用行师，征邑国也。”">​</a></h3><p>下应于三，其迹显闻，故曰“鸣谦”；最上用谦，为众所服，故“利用行师”。然声鸣其谦，必志有求焉，非如六二之正也，三止于下，如邑国之未宾也。一云：鸣谦则师有名。</p>',16)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
